-(void)pushToViewPayBillsVC {
    BOOL isPopped = false;
    for (UIViewController *controller in self.navigationController.viewControllers) {
        if ([controller isKindOfClass:[ViewPayBillsVC class]]) {
            ViewPayBillsVC *viewController = (ViewPayBillsVC*)controller;
            [self.navigationController popToViewController:viewController animated:YES];
            isPopped = true;
            return;
        }
    }

    if (!isPopped) {
        ViewPayBillsVC *viewController = (ViewPayBillsVC *)[CommonMethods viewControllerWithStoryboardName:kStoryboardViewPayBills andIdentifier:@"ViewPayBillsVC"];
        [self.navigationController pushViewController:viewController animated:YES];
    }
}

