    private fun setCurrentBalance(current: CurrentDueEntity, dueAmount: Double) {
        dueAmount.let { amountDue ->
            if (amountDue > 0) {
                amountDue(current, dueAmount)
            } else {
                noAmountDue(current)
            }
        }
    }

